/*
 * ctf_q1.h -- assets for the CTF Challenge (Konami-code easter egg).
 *   Q1_BANNER : question banner, frame 1 (full 200x200).
 *   Q1_BAND2  : middle band (rows 77..167) of frame 2, region-merged while
 *               the banner animates. 91*25 = 2275 bytes.
 *   Q1_BAND3  : rect (12,172,177,14) of frame 3, merged once after the animation.
 *               ceil(177/8)*14 = 322 bytes.
 * The success flag QR is generated at runtime (QRCode lib), not stored here.
 * Convention: MSB=left, bit 1 = white, bit 0 = black.
 * Generated by tools/gen_ctf_q1.py.
 */
#ifndef CTF_Q1_H
#define CTF_Q1_H

#define CTF_BAND_Y 77
#define CTF_BAND_H 91
#define CTF_B3_X   12
#define CTF_B3_Y   172
#define CTF_B3_W   177
#define CTF_B3_H   14
#define CTF_FLAG   "Congratulations! RHC{ROBOT_CONTROL_UNLOCKED}; Secrect command unlocked: m3mdump"
extern const unsigned char Q1_BANNER[5000];
extern const unsigned char Q1_BAND2[2275];
extern const unsigned char Q1_BAND3[322];

#endif
